def prix_initiaux_inconnus(apps, schema_editor):
    """La migration 0013 a recopié le prix de VENTE dans le prix d'achat des lots initiaux.

    Laissé ainsi, chaque boîte vendue aurait affiché un profit de zéro : un chiffre faux,
    présenté comme vrai. 0 veut dire « pas encore renseigné », et le pharmacien saisit
    le vrai prix dans la page des lots.
    """
    Lot = apps.get_model('pharmacie', 'Lot')
    Lot.objects.using(schema_editor.connection.alias).filter(numero='LOT-INITIAL').update(prix_achat=0)


def prix_initiaux_comme_avant(apps, schema_editor):
    Lot = apps.get_model('pharmacie', 'Lot')
    lots = Lot.objects.using(schema_editor.connection.alias).filter(numero='LOT-INITIAL', prix_achat=0)
    for lot in lots.select_related('medicament'):
        lot.prix_achat = lot.medicament.prix_unitaire or 0
        lot.save(update_fields=['prix_achat'])


def relier_les_lots_aux_commandes(apps, schema_editor):
    """Retrouve la commande des lots déjà reçus : même médicament, fournisseur et prix."""
    base = schema_editor.connection.alias
    Lot = apps.get_model('pharmacie', 'Lot')
    LigneCommande = apps.get_model('pharmacie', 'LigneCommande')
    for ligne in (LigneCommande.objects.using(base).filter(quantite_recue__gt=0)
                  .select_related('commande')):
        Lot.objects.using(base).filter(
            medicament_id=ligne.medicament_id,
            fournisseur_id=ligne.commande.fournisseur_id,
            prix_achat=ligne.prix_achat,
            commande__isnull=True,
        ).update(commande_id=ligne.commande_id)


